/* Enhanced focus cards with hover effects */
.day-focus-card {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
}
.day-focus-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 0.75rem;
  background: radial-gradient(circle at top right, 
    rgba(16, 185, 129, 0.05) 0%, 
    transparent 70%);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}
.day-focus-card:hover::after {
  opacity: 1;
}
.day-focus-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px -6px rgba(16, 185, 129, 0.15),
              0 4px 12px -3px rgba(0, 0, 0, 0.1);
}
/* Smart completion progress with pulsing animation */
.completion-dots-container {
  position: relative;
}
.completion-dot {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  animation: pop-in 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55) backwards;
}
.completion-dot.filled {
  animation: dot-fill 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55) backwards,
             pulse-dot 2s ease-in-out infinite;
}
@keyframes pop-in {
  0% {
    transform: scale(0);
    opacity: 0;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}
@keyframes dot-fill {
  0% {
    transform: scale(0.5);
  }
  50% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes pulse-dot {
  0%, 100% {
    box-shadow: 0 0 0 0 currentColor;
  }
  50% {
    box-shadow: 0 0 0 2px currentColor;
    opacity: 0.8;
  }
}
/* Enhanced task cards with modern design */
.day-task-card {
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  background: linear-gradient(135deg, 
    rgba(255, 255, 255, 0.98) 0%, 
    rgba(248, 250, 252, 0.95) 100%);
}
.dark .day-task-card {
  background: linear-gradient(135deg, 
    rgba(15, 23, 42, 0.6) 0%, 
    rgba(30, 41, 59, 0.7) 100%);
}
.day-task-card:hover {
  transform: translateX(4px);
  box-shadow: -4px 0 12px -2px rgba(16, 185, 129, 0.15);
}
.day-task-card.completed {
  background: linear-gradient(135deg, 
    rgba(16, 185, 129, 0.08) 0%, 
    rgba(16, 185, 129, 0.04) 100%);
}
.dark .day-task-card.completed {
  background: linear-gradient(135deg, 
    rgba(16, 185, 129, 0.15) 0%, 
    rgba(16, 185, 129, 0.08) 100%);
}
/* Workout section with distinctive styling */
.day-workout-card {
  position: relative;
  background: linear-gradient(135deg, 
    rgba(59, 130, 246, 0.05) 0%, 
    rgba(59, 130, 246, 0.02) 100%);
  border-left: 4px solid rgb(59, 130, 246);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.dark .day-workout-card {
  background: linear-gradient(135deg, 
    rgba(59, 130, 246, 0.12) 0%, 
    rgba(59, 130, 246, 0.06) 100%);
}
.day-workout-card:hover {
  transform: translateX(6px);
  box-shadow: -6px 0 16px -4px rgba(59, 130, 246, 0.3);
  border-left-color: rgb(37, 99, 235);
}
/* Day overview section with ambient glow */
.day-overview-section {
  position: relative;
  overflow: hidden;
}
.day-overview-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, 
    rgba(251, 191, 36, 0.1) 0%, 
    transparent 70%);
  opacity: 0.6;
  animation: ambient-glow 8s ease-in-out infinite;
}
@keyframes ambient-glow {
  0%, 100% {
    transform: translate(0, 0) scale(1);
    opacity: 0.6;
  }
  50% {
    transform: translate(-10%, 10%) scale(1.1);
    opacity: 0.8;
  }
}
/* Smart action buttons with hover states */
.day-action-btn {
  position: relative;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.day-action-btn::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  transform: translate(-50%, -50%);
  transition: width 0.6s, height 0.6s;
}
.day-action-btn:hover::before {
  width: 300px;
  height: 300px;
}
.day-action-btn:active {
  transform: scale(0.97);
}
/* Enhanced status bar with progress animation */
.day-status-bar {
  transition: all 0.8s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
}
.day-status-bar::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, 
    transparent 0%, 
    rgba(255, 255, 255, 0.3) 50%, 
    transparent 100%);
  animation: status-shimmer 3s ease-in-out infinite;
}
@keyframes status-shimmer {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}
/* Day health section with attention-grabbing design */
.day-health-section {
  position: relative;
  overflow: hidden;
}
.day-health-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, 
    rgba(234, 88, 12, 0) 0%, 
    rgba(234, 88, 12, 0.7) 50%, 
    rgba(234, 88, 12, 0) 100%);
  animation: health-pulse 2s ease-in-out infinite;
}
@keyframes health-pulse {
  0%, 100% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
}
/* Responsive enhancements */
@media (max-width: 640px) {
  .day-hub-header {
    backdrop-filter: blur(10px);
  }
  
  .day-task-card:hover {
    transform: translateX(2px);
  }
  
  .day-workout-card:hover {
    transform: translateX(3px);
  }
}
/* Accessibility: Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .day-hub-header::before,
  .completion-dot,
  .day-status-bar::after,
  .day-overview-section::before,
  .day-health-section::before {
    animation: none !important;
  }
  
  .day-task-card:hover,
  .day-workout-card:hover,
  .day-action-btn:hover {
    transform: none;
  }
}
/* Enhanced empty state with encouraging message */
.day-empty-state {
  position: relative;
  text-align: center;
  padding: 3rem 1.5rem;
  background: linear-gradient(135deg, 
    rgba(248, 250, 252, 0.5) 0%, 
    rgba(241, 245, 249, 0.3) 100%);
  border: 2px dashed rgba(203, 213, 225, 0.6);
  border-radius: 1rem;
  transition: all 0.3s ease;
}
.dark .day-empty-state {
  background: linear-gradient(135deg, 
    rgba(30, 41, 59, 0.3) 0%, 
    rgba(51, 65, 85, 0.2) 100%);
  border-color: rgba(71, 85, 105, 0.4);
}
.day-empty-state:hover {
  border-color: rgba(16, 185, 129, 0.5);
  background: linear-gradient(135deg, 
    rgba(16, 185, 129, 0.05) 0%, 
    rgba(16, 185, 129, 0.02) 100%);
}
.dark .day-empty-state:hover {
  border-color: rgba(16, 185, 129, 0.4);
  background: linear-gradient(135deg, 
    rgba(16, 185, 129, 0.1) 0%, 
    rgba(16, 185, 129, 0.05) 100%);
}
/* Today badge with pulse effect */
.today-badge {
  animation: badge-pulse 2s ease-in-out infinite;
}
@keyframes badge-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4);
  }
  50% {
    box-shadow: 0 0 0 4px rgba(16, 185, 129, 0);
  }
}
/* Quick stats cards */
.day-stat-card {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, 
    rgba(255, 255, 255, 0.9) 0%, 
    rgba(248, 250, 252, 0.95) 100%);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(226, 232, 240, 0.8);
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.dark .day-stat-card {
  background: linear-gradient(135deg, 
    rgba(30, 41, 59, 0.6) 0%, 
    rgba(51, 65, 85, 0.5) 100%);
  border: 1px solid rgba(71, 85, 105, 0.5);
}
.day-stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, 
    transparent 0%, 
    rgba(16, 185, 129, 0.6) 50%, 
    transparent 100%);
  opacity: 0;
  transition: opacity 0.3s ease;
}
.day-stat-card:hover::before {
  opacity: 1;
}
.day-stat-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px -6px rgba(16, 185, 129, 0.2);
  border-color: rgba(16, 185, 129, 0.4);
}
/* Floating action hints */
.action-hint {
  position: relative;
  animation: float-hint 3s ease-in-out infinite;
}
@keyframes float-hint {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}
/* ================================================================
   DAY VIEW REDESIGN — New Component Styles
   Week strip, progress ring, tabs, timeline, filter chips
   ================================================================ */
/* ===== HERO GRID ===== */
.day-hero-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}
@media (min-width: 768px) {
  .day-hero-grid {
    grid-template-columns: 1fr auto;
    align-items: start;
  }
}
.day-hero-left {
  min-width: 0;
}
.day-hero-right {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
}
@media (max-width: 767px) {
  .day-hero-right {
    flex-direction: row;
    align-items: center;
    gap: 1.5rem;
    justify-content: center;
  }
}
/* ===== CIRCULAR PROGRESS RING ===== */
.day-progress-ring-wrap {
  position: relative;
  width: 8.5rem;
  height: 8.5rem;
  flex-shrink: 0;
}
.day-progress-ring {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.ring-track {
  stroke: rgba(226, 232, 240, 1);
}
.dark .ring-track {
  stroke: rgba(51, 65, 85, 0.8);
}
.ring-progress {
  stroke: rgb(59, 130, 246);
  transition: stroke-dashoffset 1s cubic-bezier(0.4, 0, 0.2, 1);
}
.ring-progress.ring-green {
  stroke: rgb(16, 185, 129);
}
/* Gold ring for fully completed day (GREEN status) */
.ring-progress.ring-gold {
  stroke: rgb(251, 191, 36);
}
/* Emerald ring for partially completed (ORANGE status) */
.ring-progress.ring-emerald {
  stroke: rgb(16, 185, 129);
}
/* Blue ring for today in-progress (BLUE status) */
.ring-progress.ring-blue {
  stroke: rgb(59, 130, 246);
}
.ring-progress.ring-orange {
  stroke: rgb(245, 158, 11);
}
.ring-progress.ring-red {
  stroke: rgb(239, 68, 68);
}
.ring-progress.ring-default {
  stroke: rgb(148, 163, 184);
}
.ring-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.ring-pct {
  font-size: 1.375rem;
  font-weight: 800;
  line-height: 1;
  color: rgb(15, 23, 42);
}
.dark .ring-pct {
  color: rgb(241, 245, 249);
}
.ring-label {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: rgb(100, 116, 139);
  margin-top: 0.25rem;
}
.dark .ring-label {
  color: rgb(148, 163, 184);
}
/* ===== QUICK STAT PILLS ===== */
.day-quick-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
}
@media (min-width: 768px) {
  .day-quick-stats {
    flex-direction: column;
    align-items: stretch;
    width: 8.5rem;
  }
}
.day-stat-pill {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border-radius: 0.625rem;
  border: 1px solid rgba(226, 232, 240, 0.8);
  background: rgba(248, 250, 252, 0.9);
  padding: 0.375rem 0.625rem;
  min-width: 5.5rem;
}
.dark .day-stat-pill {
  border-color: rgba(51, 65, 85, 0.6);
  background: rgba(30, 41, 59, 0.5);
}
@media (min-width: 768px) {
  .day-stat-pill {
    min-width: 0;
    width: 100%;
  }
}
.stat-pill-val {
  font-size: 0.9375rem;
  font-weight: 700;
  color: rgb(15, 23, 42);
}
.dark .stat-pill-val {
  color: rgb(241, 245, 249);
}
.stat-pill-key {
  font-size: 0.6875rem;
  font-weight: 500;
  color: rgb(100, 116, 139);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.dark .stat-pill-key {
  color: rgb(148, 163, 184);
}
/* ===== WEEK CONTEXT STRIP ===== */
.day-week-strip {
  transition: border-color 0.2s ease;
}
.day-week-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.125rem;
  border-radius: 0.875rem;
  padding: 0.5rem 0.75rem;
  border: 1.5px solid transparent;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  text-decoration: none;
  min-width: 3.25rem;
  cursor: pointer;
}
.day-week-btn:hover {
  background: rgba(241, 245, 249, 0.9);
  border-color: rgba(203, 213, 225, 0.8);
}
.dark .day-week-btn:hover {
  background: rgba(30, 41, 59, 0.6);
  border-color: rgba(71, 85, 105, 0.6);
}
.day-week-btn.active,
.day-week-btn[aria-current="page"] {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.12) 0%, rgba(16, 185, 129, 0.06) 100%);
  border-color: rgba(16, 185, 129, 0.5);
  box-shadow: 0 2px 8px -2px rgba(16, 185, 129, 0.25);
}
.dark .day-week-btn.active,
.dark .day-week-btn[aria-current="page"] {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.18) 0%, rgba(16, 185, 129, 0.1) 100%);
  border-color: rgba(16, 185, 129, 0.5);
}
.day-week-btn__name {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgb(100, 116, 139);
}
.dark .day-week-btn__name {
  color: rgb(148, 163, 184);
}
.day-week-btn.active .day-week-btn__name,
.day-week-btn[aria-current="page"] .day-week-btn__name {
  color: rgb(5, 150, 105);
}
/* ===== CONTAINED TAB WORKSPACE ===== */
.day-tabs-container {
  margin-left: auto;
  margin-right: auto;
  max-width: 72rem;
}
.day-tab-panel > section,
.day-tab-panel > div {
  margin-left: auto;
  margin-right: auto;
  max-width: 72rem;
}
#tab-panel-overview .day-overview-section {
  max-height: 34rem;
  overflow-y: auto;
}
/* ===== UNIFIED ACTION SYSTEM ===== */
.day-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.75rem;
  padding: 0.5rem 0.9rem;
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1;
  border: 1px solid transparent;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease, color 0.18s ease;
}
.day-action-btn:hover {
  transform: translateY(-1px);
}
.day-action-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.28);
}
.day-action-btn--primary {
  background: linear-gradient(135deg, rgb(15, 23, 42), rgb(30, 41, 59));
  color: rgb(248, 250, 252);
}
.dark .day-action-btn--primary {
  background: linear-gradient(135deg, rgb(226, 232, 240), rgb(248, 250, 252));
  color: rgb(15, 23, 42);
}
.day-action-btn--secondary {
  border-color: rgba(203, 213, 225, 0.9);
  background: rgba(255, 255, 255, 0.95);
  color: rgb(15, 23, 42);
}
.dark .day-action-btn--secondary {
  border-color: rgba(71, 85, 105, 0.8);
  background: rgba(15, 23, 42, 0.7);
  color: rgb(226, 232, 240);
}
.day-action-btn--ghost {
  border-color: rgba(148, 163, 184, 0.5);
  background: transparent;
  color: rgb(71, 85, 105);
}
.dark .day-action-btn--ghost {
  border-color: rgba(100, 116, 139, 0.8);
  color: rgb(148, 163, 184);
}
.day-action-btn--danger {
  border-color: rgba(254, 202, 202, 0.9);
  background: rgba(255, 255, 255, 0.95);
  color: rgb(185, 28, 28);
}
.dark .day-action-btn--danger {
  border-color: rgba(127, 29, 29, 0.6);
  background: rgba(15, 23, 42, 0.65);
  color: rgb(252, 165, 165);
}
.day-action-chip {
  display: inline-flex;
  align-items: center;
  border-radius: 9999px;
  padding: 0.35rem 0.6rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: rgb(5, 150, 105);
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.25);
}
/* ===== TASKS + WORKOUTS ROWS ===== */
.day-task-row,
.day-workout-row {
  position: relative;
  overflow: hidden;
}
.day-task-row::before,
.day-workout-row::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: radial-gradient(circle at top right, rgba(56, 189, 248, 0.08), transparent 60%);
  opacity: 0;
  transition: opacity 0.2s ease;
}
.day-task-row:hover::before,
.day-workout-row:hover::before {
  opacity: 1;
}
/* ===== DRAWER TRANSITIONS ===== */
#task-drawer,
#workout-drawer {
  transition: opacity 0.2s ease;
}
#task-drawer .sm\:w-96,
#workout-drawer .sm\:w-\[28rem\] {
  transition: transform 0.24s ease;
}
#task-drawer.hidden .sm\:w-96,
#workout-drawer.hidden .sm\:w-\[28rem\] {
  transform: translateX(24px);
}
/* ===== TIMELINE DRAG AFFORDANCES ===== */
.timeline-event[draggable="true"] {
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
}
.timeline-slot.timeline-drop-over {
  border-radius: 0.6rem;
  background: rgba(16, 185, 129, 0.12);
  box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.35);
}
.timeline-event--workout {
  border-left: 3px solid rgba(16, 185, 129, 0.7);
}
.timeline-event--task {
  border-left: 3px solid rgba(59, 130, 246, 0.7);
}
.dark .day-week-btn.active .day-week-btn__name,
.dark .day-week-btn[aria-current="page"] .day-week-btn__name {
  color: rgb(52, 211, 153);
}
.day-week-btn__num {
  font-size: 1rem;
  font-weight: 700;
  color: rgb(30, 41, 59);
  line-height: 1.1;
}
.dark .day-week-btn__num {
  color: rgb(226, 232, 240);
}
.day-week-btn.active .day-week-btn__num,
.day-week-btn[aria-current="page"] .day-week-btn__num {
  color: rgb(5, 150, 105);
}
.dark .day-week-btn.active .day-week-btn__num,
.dark .day-week-btn[aria-current="page"] .day-week-btn__num {
  color: rgb(52, 211, 153);
}
/* ===== SECTION TABS ===== */
.day-tab-nav {
  display: flex;
  align-items: stretch;
  gap: 0;
  border-radius: 0.875rem 0.875rem 0 0;
  background: rgba(248, 250, 252, 0.8);
  border: 1px solid rgb(226, 232, 240);
  border-bottom: none;
  padding: 0.375rem 0.375rem 0;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.day-tab-nav::-webkit-scrollbar {
  display: none;
}
.dark .day-tab-nav {
  background: rgba(15, 23, 42, 0.7);
  border-color: rgb(51, 65, 85);
}
.day-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.875rem;
  font-size: 0.8125rem;
  font-weight: 600;
  color: rgb(71, 85, 105);
  border-radius: 0.625rem 0.625rem 0 0;
  border: 1.5px solid transparent;
  border-bottom: none;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  background: transparent;
  flex-shrink: 0;
}
.dark .day-tab-btn {
  color: rgb(148, 163, 184);
}
.day-tab-btn:hover {
  color: rgb(15, 23, 42);
  background: rgba(255, 255, 255, 0.7);
}
.dark .day-tab-btn:hover {
  color: rgb(226, 232, 240);
  background: rgba(30, 41, 59, 0.5);
}
.day-tab-btn.is-active,
.day-tab-btn[aria-selected="true"] {
  color: rgb(37, 99, 235);
  background: rgb(255, 255, 255);
  border-color: rgb(226, 232, 240);
  border-bottom-color: rgb(255, 255, 255);
  box-shadow: 0 -2px 8px -4px rgba(59, 130, 246, 0.2);
  margin-bottom: -1px;
  padding-bottom: calc(0.5rem + 1px);
}
.dark .day-tab-btn.is-active,
.dark .day-tab-btn[aria-selected="true"] {
  color: rgb(96, 165, 250);
  background: rgb(15, 23, 42);
