/* ===== VIEW TOGGLE ===== */
.calendar-view-mode-toggle {
  display: inline-flex;
  align-items: center;
  padding: 0.3rem;
  border-radius: 0.9rem;
  border: 1px solid rgb(226, 232, 240);
