  font-size: 0.8rem;
  font-weight: 700;
  border-radius: 0.65rem;
  border: 1px solid transparent;
  background: transparent;
  color: rgb(100, 116, 139);
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}
.calendar-view-mode-btn:hover {
  color: rgb(30, 41, 59);
