#sticker-view-panel.sticker-view-active {
  display: block;
}
/* ===== MONTHLY TARGET BAR ===== */
.sticker-target-bar {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.25rem;
  border-radius: 0.85rem;
  background: rgba(248, 250, 252, 0.9);
  border: 1px solid rgb(226, 232, 240);
