    font-weight: 500;
    --tw-text-opacity: 1;
    color: rgb(51 65 85 / var(--tw-text-opacity, 1));
    --tw-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --tw-shadow-colored: 0 1px 2px 0 var(--tw-shadow-color);
    box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
    transition-property: color, background-color, border-color, text-decoration-color, fill, stroke;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
    transition-duration: 100ms;
}
.vault-action-btn:hover {
    --tw-bg-opacity: 1;
    background-color: rgb(248 250 252 / var(--tw-bg-opacity, 1));
}
.vault-action-btn:is(.dark *) {
    border-color: rgb(255 255 255 / 0.1);
    --tw-bg-opacity: 1;
    background-color: rgb(30 41 59 / var(--tw-bg-opacity, 1));
    --tw-text-opacity: 1;
    color: rgb(226 232 240 / var(--tw-text-opacity, 1));
}
.vault-action-btn:hover:is(.dark *) {
    --tw-bg-opacity: 1;
    background-color: rgb(51 65 85 / var(--tw-bg-opacity, 1));
}
.vault-action-btn.destructive {
    --tw-border-opacity: 1;
    border-color: rgb(254 205 211 / var(--tw-border-opacity, 1));
    --tw-text-opacity: 1;
    color: rgb(225 29 72 / var(--tw-text-opacity, 1));
}
.vault-action-btn.destructive:hover {
    --tw-bg-opacity: 1;
    background-color: rgb(255 241 242 / var(--tw-bg-opacity, 1));
}
.vault-action-btn.destructive:is(.dark *) {
    border-color: rgb(159 18 57 / 0.4);
    --tw-text-opacity: 1;
    color: rgb(251 113 133 / var(--tw-text-opacity, 1));
}
.vault-action-btn.destructive:hover:is(.dark *) {
    background-color: rgb(136 19 55 / 0.2);
}
/* ── Empty State ────────────────────────────────────────────── */
.vault-empty {
    margin-top: 1rem;
    border-radius: 0.75rem;
    border-width: 2px;
    border-style: dashed;
    --tw-border-opacity: 1;
    border-color: rgb(226 232 240 / var(--tw-border-opacity, 1));
    --tw-bg-opacity: 1;
    background-color: rgb(255 255 255 / var(--tw-bg-opacity, 1));
    padding: 2.5rem;
    text-align: center;
}
.vault-empty:is(.dark *) {
    border-color: rgb(255 255 255 / 0.1);
    background-color: rgb(255 255 255 / 0.05);
}
.vault-empty-icon {
    margin-left: auto;
    margin-right: auto;
    margin-bottom: 1rem;
    display: flex;
    height: 3.5rem;
    width: 3.5rem;
    align-items: center;
    justify-content: center;
    border-radius: 9999px;
    --tw-bg-opacity: 1;
    background-color: rgb(209 250 229 / var(--tw-bg-opacity, 1));
    --tw-text-opacity: 1;
    color: rgb(5 150 105 / var(--tw-text-opacity, 1));
}
.color-blind .vault-empty-icon {
    --tw-text-opacity: 1;
    color: rgb(13 148 136 / var(--tw-text-opacity, 1));
}
.week-day-card:has(.vault-empty-icon:is(.dark *)) {
        border-color: rgba(16, 185, 129, 0.5);
        background: linear-gradient(135deg, rgba(16, 185, 129, 0.1) 0%, rgba(16, 185, 129, 0.05) 100%);
    }
html:not(.dark) .week-day-card:has(.vault-empty-icon:is(.dark *)) {
        background: linear-gradient(135deg, rgba(16, 185, 129, 0.08) 0%, rgba(16, 185, 129, 0.04) 100%);
        border-color: rgba(16, 185, 129, 0.3);
    }
.vault-empty-icon:is(.dark *) {
    background-color: rgb(16 185 129 / 0.1);
    --tw-text-opacity: 1;
    color: rgb(52 211 153 / var(--tw-text-opacity, 1));
}
.vault-empty-title {
    font-size: 1rem;
    line-height: 1.5rem;
    font-weight: 600;
    --tw-text-opacity: 1;
    color: rgb(15 23 42 / var(--tw-text-opacity, 1));
}
.vault-empty-title:is(.dark *) {
    --tw-text-opacity: 1;
    color: rgb(241 245 249 / var(--tw-text-opacity, 1));
}
.vault-empty-body {
    margin-left: auto;
    margin-right: auto;
    margin-top: 0.25rem;
    max-width: 20rem;
    font-size: 0.875rem;
    line-height: 1.25rem;
    --tw-text-opacity: 1;
    color: rgb(100 116 139 / var(--tw-text-opacity, 1));
}

.pricing-page .vault-empty-body {
    color: var(--pricing-muted);
}

.store-page .vault-empty-body {
    color: var(--store-muted);
}
.vault-empty-body:is(.dark *) {
    --tw-text-opacity: 1;
    color: rgb(148 163 184 / var(--tw-text-opacity, 1));
}
/* ── AI Insight Panel (top of vault) ────────────────────────── */
.vault-ai-panel {
    border-radius: 0.75rem;
    border-width: 1px;
    --tw-border-opacity: 1;
    border-color: rgb(221 214 254 / var(--tw-border-opacity, 1));
    background-image: linear-gradient(to right, var(--tw-gradient-stops));
    --tw-gradient-from: #f5f3ff var(--tw-gradient-from-position);
    --tw-gradient-to: rgb(245 243 255 / 0) var(--tw-gradient-to-position);
    --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to);
    --tw-gradient-to: #fff var(--tw-gradient-to-position);
    padding: 1rem;
    --tw-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --tw-shadow-colored: 0 1px 2px 0 var(--tw-shadow-color);
    box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);
}
.vault-ai-panel:is(.dark *) {
    border-color: rgb(109 40 217 / 0.3);
    --tw-gradient-from: rgb(76 29 149 / 0.2) var(--tw-gradient-from-position);
    --tw-gradient-to: rgb(76 29 149 / 0) var(--tw-gradient-to-position);
    --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to);
    --tw-gradient-to: rgb(255 255 255 / 0.05) var(--tw-gradient-to-position);
}
.vault-ai-panel-title {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.875rem;
    line-height: 1.25rem;
    font-weight: 600;
    --tw-text-opacity: 1;
    color: rgb(76 29 149 / var(--tw-text-opacity, 1));
}
body[data-easy-mode="on"] .vault-ai-panel-title {
    gap: 0.75rem;
}
.vault-ai-panel-title:is(.dark *) {
    --tw-text-opacity: 1;
    color: rgb(221 214 254 / var(--tw-text-opacity, 1));
}
.vault-ai-panel-body {
    margin-top: 0.5rem;
    white-space: pre-wrap;
    font-size: 0.875rem;
    line-height: 1.25rem;
    line-height: 1.625;
    --tw-text-opacity: 1;
    color: rgb(91 33 182 / var(--tw-text-opacity, 1));
}
.vault-ai-panel-body:is(.dark *) {
    --tw-text-opacity: 1;
    color: rgb(196 181 253 / var(--tw-text-opacity, 1));
}
/* ── Responsive Adjustments ─────────────────────────────────── */
@media (max-width: 640px) {
    .vault-cards {
        grid-template-columns: repeat(1, minmax(0, 1fr));
    }

    .vault-card-actions {
        pointer-events: auto;
        position: static;
        margin-top: 0.75rem;
        justify-content: flex-start;
        border-radius: 0px;
        background-image: none;
        padding-left: 0px;
        padding-right: 0px;
        padding-top: 0px;
        padding-bottom: 0px;
        opacity: 1;
    }
}
.store-page {
    --store-bg: #ffffff;
    --store-text: #111827;
    --store-muted: #4b5563;
    --store-emerald: #059669;
    --store-emerald-strong: #047857;
