.store-hero {
    position: relative;
    overflow: hidden;
    padding: 4rem 1rem 3rem;
    text-align: center;
}
.store-hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
        radial-gradient(ellipse 70% 50% at 30% 0%, rgba(5, 150, 105, 0.12) 0%, transparent 65%),
        radial-gradient(ellipse 50% 40% at 70% 100%, rgba(16, 185, 129, 0.08) 0%, transparent 65%);
    pointer-events: none;
}
.store-hero-grid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(5, 150, 105, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(5, 150, 105, 0.05) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
}
.cat-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.45rem 1rem;
    border-radius: 99px;
    font-size: 0.8rem;
    font-weight: 600;
    border: 1px solid rgba(5, 150, 105, 0.3);
    background: rgba(5, 150, 105, 0.06);
    color: #374151;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
}
.cat-pill:hover,
.cat-pill.active {
    border-color: rgba(5, 150, 105, 0.6);
    background: rgba(5, 150, 105, 0.14);
    color: #047857;
    box-shadow: 0 8px 18px rgba(5, 150, 105, 0.14);
}
.cat-pill.all.active {
    background: rgba(5, 150, 105, 0.14);
    border-color: rgba(5, 150, 105, 0.5);
    color: #047857;
}
.product-card {
    background: #ffffff;
    border: 1px solid var(--store-border);
    border-radius: 1rem;
    overflow: hidden;
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.3s ease, border-color 0.3s ease;
    display: flex;
    flex-direction: column;
}
.product-card:hover {
    transform: translateY(-5px);
    border-color: rgba(5, 150, 105, 0.5);
    box-shadow: 0 14px 28px rgba(17, 24, 39, 0.1);
}
.product-card.out-of-stock {
    opacity: 0.65;
}
.product-img-wrap {
    position: relative;
    width: 100%;
    padding-top: 100%;
    overflow: hidden;
    background: #f9fafb;
}
.product-img-wrap img,
.product-img-wrap .img-placeholder {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    -o-object-fit: cover;
       object-fit: cover;
    transition: transform 0.4s ease, opacity 0.4s ease;
}
.product-img-wrap img.img-back {
    opacity: 0;
}
.product-card:hover .product-img-wrap img.img-front {
    opacity: 0;
    transform: scale(1.06);
}
.product-card:hover .product-img-wrap img.img-back {
    opacity: 1;
    transform: scale(1.06);
}
.product-card:hover .product-img-wrap img:only-of-type {
    transform: scale(1.06);
    opacity: 1;
}
.product-img-wrap .img-placeholder {
    display: flex;
    align-items: center;
    justify-content: center;
}
.stock-badge {
    position: absolute;
    top: 0.6rem;
    right: 0.6rem;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.2rem 0.6rem;
    border-radius: 99px;
}
.cat-tag {
    position: absolute;
    top: 0.6rem;
    left: 0.6rem;
    font-size: 0.7rem;
    font-weight: 600;
    padding: 0.2rem 0.6rem;
    border-radius: 99px;
    background: rgba(255, 255, 255, 0.96);
    border: 1px solid rgba(5, 150, 105, 0.28);
    color: #047857;
    backdrop-filter: blur(4px);
}
.demo-banner {
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.08), rgba(5, 150, 105, 0.06));
    border: 1px solid rgba(5, 150, 105, 0.28);
    border-radius: 1rem;
    padding: 1rem 1.25rem;
}
.featured-strip {
    position: relative;
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.08) 0%, rgba(5, 150, 105, 0.06) 100%);
    border: 1px solid rgba(5, 150, 105, 0.2);
    border-radius: 1.25rem;
    overflow: hidden;
}
.featured-strip::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: linear-gradient(90deg, transparent, #10b981, #059669, transparent);
}
.store-surface-highlight {
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid rgba(5, 150, 105, 0.22);
}
.store-surface-highlight-soft {
    background: rgba(16, 185, 129, 0.08);
    border: 1px solid rgba(5, 150, 105, 0.2);
}
.store-surface-panel {
    background: rgba(16, 185, 129, 0.06);
    border: 1px solid rgba(5, 150, 105, 0.18);
}
.store-feature-icon-surface {
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid rgba(5, 150, 105, 0.25);
}
@media (prefers-reduced-motion: reduce) {
    .product-card { transition: none; }
    .product-card:hover { transform: none; }
}
/* ===== Timeline day tooltip (outside @layer to avoid specificity issues) ===== */
.cd-day-tooltip {
    position: fixed;
    z-index: 9999;
    pointer-events: none;
    padding: 0.4rem 0.7rem;
    border-radius: 0.5rem;
    font-size: 0.75rem;
    line-height: 1.5;
    white-space: nowrap;
    opacity: 0;
    transform: translateY(4px);
    transition: opacity 0.15s ease, transform 0.15s ease;
    background: rgba(15, 23, 42, 0.92);
    border: 1px solid rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(8px);
    color: #e2e8f0;
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}
.cd-day-tooltip--visible {
    opacity: 1;
    transform: translateY(0);
